#!/usr/bin/env bash
# tools/sanitize_history.sh
# Purges AI co-author bylines, prompt traces, private paths, and internal host details
# before publishing to public git origin.

set -euo pipefail

REPO_DIR="${1:-.}"
cd "$REPO_DIR"

echo "=== Reading Room Pre-Release Sanitization Gate ==="

# 1. Audit check for sensitive markers
PATTERNS=(
  "Co-Authored-By: Claude"
  "Co-Authored-By: Anthropic"
  "Claude Opus"
  "Claude Sonnet"
  "Generated by Claude"
  "/home/"
  "/Users/"
)

# Host names, tailnet addresses and other private markers live in an untracked
# file, one pattern per line, so this public script does not publish them.
PRIVATE_PATTERNS="${SANITIZE_PATTERNS_FILE:-.sanitize-patterns}"
if [ -f "$PRIVATE_PATTERNS" ]; then
  while IFS= read -r line; do
    [ -n "$line" ] && [ "${line#\#}" = "$line" ] && PATTERNS+=("$line")
  done < "$PRIVATE_PATTERNS"
elif [ "${SANITIZE_GENERIC_ONLY:-}" = "1" ]; then
  echo "  [WARN] $PRIVATE_PATTERNS not found; SANITIZE_GENERIC_ONLY=1, scanning generic patterns only"
else
  echo "  [FAIL] $PRIVATE_PATTERNS not found. Create it (one pattern per line), or set"
  echo "         SANITIZE_GENERIC_ONLY=1 to knowingly scan generic patterns only."
  exit 1
fi

echo "--- Scanning commit history for sensitive tokens ---"
FOUND=0
for p in "${PATTERNS[@]}"; do
  COUNT=$(git log --all --grep="$p" -F --oneline 2>/dev/null | wc -l)
  if [ "$COUNT" -gt 0 ]; then
    echo "  [FOUND] Pattern: '$p' in $COUNT commit messages"
    FOUND=1
  fi
done

echo "--- Scanning committed file content for private paths ---"
MATCHES=""
for p in "${PATTERNS[@]}"; do
  case "$p" in Co-Authored-By*|Claude*|Generated*) continue ;; esac
  MATCHES+=$(git grep -nF "$p" HEAD -- ':!tools/sanitize_history.sh' 2>/dev/null || true)
done
if [ -n "$MATCHES" ]; then
  echo "  [FAIL] Found private paths in repository tree:"
  echo "$MATCHES"
  FOUND=1
else
  echo "  [PASS] Clean file content tree. No private paths detected."
fi

if [ "$FOUND" -eq 0 ]; then
  echo "=== All checks PASSED. Repository is clean for public publication ==="
  exit 0
fi

echo ""
echo "Notice: Detected markers requiring sanitization."
echo "To purge commit messages with git-filter-repo, run:"
echo "  git-filter-repo --message-callback '"
echo "    import re"
echo "    msg = re.sub(r\"(?i)Co-Authored-By:.*Claude.*\\n?\", \"\", message.decode())"
echo "    msg = re.sub(r\"(?i)Co-Authored-By:.*Anthropic.*\\n?\", \"\", msg)"
echo "    return msg.encode()'"
echo ""
exit 1
